/**
 * dsh-market-pro client plugin: the browser half of the safe plugin
 * marketplace. Mounts the dshMarketPro Remote namespace, contributes the
 * market pages to the left navigation and right sidebar, and owns the review
 * hand-off — which opens a session in the current or most recent workspace and
 * stages a security-review prompt in its composer.
 *
 * Nothing is sent. The draft is written through the published conversation
 * face and left there: the person at the keyboard reads the prompt and presses
 * Enter to begin a read-only audit of already-installed artifacts.
 */
// Type-only: the ctx.remote merge and the forwarded Host-event face.
import type {} from '@deepseek-ai/dsh-api-remotes/client'
import type { ISessions } from '@deepseek-ai/dsh-api-session-controller/client'
import type { Context as ClientContext } from '@deepseek-ai/cordis'
// Type-only: the ctx.locale Context merge.
import type {} from '@deepseek-ai/dsh-client-locale/client'
// Type-only: pulls the SlotRegistry service merge (ctx.slots).
import type {} from '@deepseek-ai/dsh-client-ui-renderer/client'
import type { IConversation } from '@deepseek-ai/dsh-client-ui-conversation/client'
import type {
  McpAdoptResult,
  McpHostContext,
  MarketCatalogResult,
  MarketEnvironment,
  MarketInstalledResult,
  MarketSkillsResult,
  SafeMarketSettings,
} from '../contract.ts'
import { createDirectInstaller, type InstallHost } from './directInstall.ts'
import {
  createMcpController, type McpCredentialsFace, type McpManagerFace, type McpPluginsFace, type McpSettingsFace,
} from './mcpController.ts'
import { createPluginUpdater, type UpdateHost, type UpdateMarketHost } from './pluginUpdates.ts'
import { stageReviewPrompt } from './handoff.ts'
import { SAFE_MARKET_REMOTE } from './remote.ts'
import {
  type ChooseWorkspaceOutcome,
  type InstallOutcome,
  type MarketSectionInjected,
  type WorkspaceReadiness,
} from './MarketSection.tsx'
import { NO_SESSION, SESSIONS_PENDING, ProjectSkillsView } from './SkillsView.tsx'
import { en, zh, type SafeMarketLocaleKey } from './locales.ts'
import { adoptStyles } from './styles.ts'
import { registerMarketNavigation, registerMarketSidebar, registerMarketPluginTab } from './sidebar.tsx'
import {
  type MarketUiWorkspace,
  type MarketWorkspaces,
  type WorkspaceTarget,
  currentSessionOf,
  workspaceReady,
  workspaceTargetOf,
} from './workspaceCompat.ts'

export type {
  ChooseWorkspaceOutcome,
  InstallOutcome,
  MarketSectionInjected,
  MarketSectionProps,
  WorkspaceReadiness,
} from './MarketSection.tsx'
export type { SafeMarketLocaleKey } from './locales.ts'
export { NO_SESSION, SESSIONS_PENDING } from './SkillsView.tsx'

declare module '@deepseek-ai/dsh-client-ui-slots' {
  interface LocaleNamespaceMap {
    /** The safe plugin marketplace's copy. */
    'settings.dshMarketPro': SafeMarketLocaleKey
  }
}

/** Dictionary namespace owned by this plugin. */
export const NS = 'settings.dshMarketPro'

/** Required DSH services: locale, Remote, split Controllers, navigation, and conversation. */
export const inject = ['slots', 'locale', 'remote', 'sessions', 'workspaces', 'uiWorkspace', 'conversation']

/** Poll only for the newly registered workspace to reach its list mirror. */
const WORKSPACE_POLL_MS = 60
/** How long a freshly registered workspace gets to reach the list mirror. */
const WORKSPACE_WAIT_MS = 4_000

/** A dependency-free root store; its identity and snapshots stay stable between writes. */
function createMarketStore<T>(initial: T): {
  getSnapshot(): T
  subscribe(listener: () => void): () => void
  set(next: T): void
} {
  let value = initial
  const listeners = new Set<() => void>()
  return {
    getSnapshot: () => value,
    subscribe: (listener) => {
      listeners.add(listener)
      return () => { listeners.delete(listener) }
    },
    set: (next) => {
      if (Object.is(value, next)) return
      value = next
      for (const listener of [...listeners]) listener()
    },
  }
}

/** The mounted dshMarketPro namespace service's callable face. */
interface SafeMarketFace {
  getCatalog(force: boolean, signal?: AbortSignal): Promise<{ ok: true; value: MarketCatalogResult } | { ok: false; error: { code: string; message: string } }>
  listSkills(sessionId: string, signal?: AbortSignal): Promise<{ ok: true; value: MarketSkillsResult } | { ok: false; error: { code: string; message: string } }>
  describe(): Promise<{ ok: true; value: MarketEnvironment } | { ok: false; error: { code: string; message: string } }>
  getSettings(): Promise<{ ok: true; value: SafeMarketSettings } | { ok: false; error: { code: string; message: string } }>
  listInstalled(): Promise<{ ok: true; value: MarketInstalledResult } | { ok: false; error: { code: string; message: string } }>
  setInstalledEnabled(update: { packageName: string; enabled: boolean }): Promise<{ ok: true; value: MarketInstalledResult } | { ok: false; error: { code: string; message: string } }>
  uninstallInstalled(update: { packageName: string }): Promise<{ ok: true; value: MarketInstalledResult } | { ok: false; error: { code: string; message: string } }>
  inspectMcp(): Promise<{ ok: true; value: McpHostContext } | { ok: false; error: { code: string; message: string } }>
  adoptMcp(request: { loaderId: string }): Promise<{ ok: true; value: McpAdoptResult } | { ok: false; error: { code: string; message: string } }>
}

/** The slice of the Host's session namespace the folder action calls. */
interface SessionPathFace {
  canOpenWorkspacePath(): Promise<{ ok: true; value: boolean } | { ok: false; error: { code: string; message: string } }>
  openWorkspacePath(request: { path: string }): Promise<{ ok: true; value: { opened: true } } | { ok: false; error: { code: string; message: string } }>
}

const defaultSettings = (): SafeMarketSettings => ({ enabled: false })

function wait(ms: number): Promise<void> {
  return new Promise((resolve) => { setTimeout(resolve, ms) })
}

/**
 * Compose the marketplace surface.
 * @param ctx - client root context.
 */
export function apply(ctx: ClientContext): void {
  ctx.effect(() => adoptStyles(), 'dsh-market-pro: styles')
  ctx.effect(() => ctx.locale.register(NS, { zh, en }), 'dsh-market-pro: dictionaries')

  const scope = createMarketStore({ value: defaultSettings(), settingsReady: false, profile: null as string | null, version: '' })
  let settingsGeneration = 0

  const workspaces = ctx.get('workspaces') as MarketWorkspaces
  const sessions = ctx.get('sessions') as ISessions
  const navigation = ctx.get('uiWorkspace') as MarketUiWorkspace

  const reportError = (operation: string, error: unknown): void => {
    console.error(`[dsh-market-pro] ${operation} failed:`, error)
  }

  // The mounted namespace handle resolves through the service store
  // (`ctx.reflect.get`), not through `ctx.remote.dshMarketPro`: the dotted read
  // walks the cordis fiber chain, which stops at the Loader's runtime-less
  // internal forks between a plugin entry and the root fiber.
  let market: SafeMarketFace | undefined

  const loadSettings = async (): Promise<void> => {
    const remote = market
    if (remote === undefined) return
    const generation = ++settingsGeneration
    try {
      const result = await remote.getSettings()
      if (market !== remote || generation !== settingsGeneration) return
      if (!result.ok) {
        reportError('settings read', result.error)
        return
      }
      scope.set({ ...scope.getSnapshot(), value: result.value, settingsReady: true })
    } catch (error) {
      if (market === remote && generation === settingsGeneration) reportError('settings read', error)
    }
  }

  /**
   * The deployment facts the review prompt needs. Read once per mount: the
   * profile a Host boots does not change under a running client.
   */
  const loadEnvironment = async (): Promise<void> => {
    const remote = market
    if (remote === undefined) return
    try {
      const result = await remote.describe()
      if (market !== remote) return
      if (!result.ok) {
        reportError('describe', result.error)
        return
      }
      scope.set({ ...scope.getSnapshot(), profile: result.value.profile, version: result.value.version })
    } catch (error) {
      if (market === remote) reportError('describe', error)
    }
  }

  ctx.effect(async () => {
    const dispose = await ctx.remote.$mount(SAFE_MARKET_REMOTE)
    market = (ctx.reflect as unknown as { get(name: string): unknown }).get('remote.dshMarketPro') as SafeMarketFace | undefined
    if (market === undefined) {
      throw new Error('dsh-market-pro: the dshMarketPro Remote namespace did not mount')
    }
    await Promise.all([loadSettings(), loadEnvironment()])
    return () => {
      settingsGeneration += 1
      market = undefined
      void dispose()
    }
  }, 'dsh-market-pro: remote')

  // Reconnect may have rebuilt the host: the durable switch and the
  // deployment facts are re-read rather than assumed to have survived.
  ctx.on('connection/reset', () => {
    void loadSettings()
    void loadEnvironment()
  })

  // Invalidate both entry points when installed providers change.
  const skillRevision = createMarketStore(0)
  const refreshSkills = () => skillRevision.set(skillRevision.getSnapshot() + 1)
  ctx.effect(() => ctx.remote.$on('plugin-manager/changed', refreshSkills), 'dsh-market-pro: skill providers changed')
  ctx.effect(() => {
    window.addEventListener('focus', refreshSkills)
    return () => window.removeEventListener('focus', refreshSkills)
  }, 'dsh-market-pro: refresh skills on focus')

  const skillsFor = (sessionId?: NonNullable<ReturnType<typeof currentSessionOf>>) => {
    const selection = () => {
      const state = sessions.list.getSnapshot()
      const id = sessionId ?? currentSessionOf(state)
      const row = id === undefined ? undefined : state.byId[id]
      const projected = row?.projectionValues as { agentPreset?: string; workingDirectory?: string | null } | undefined
      return { phase: state.phase, id, preset: projected?.agentPreset, cwd: projected?.workingDirectory ?? row?.cwd }
    }
    return {
      listSkills: async (): Promise<MarketSkillsResult> => {
        const { phase, id } = selection()
        if (phase !== 'ready') return { skills: [], complete: true, error: SESSIONS_PENDING }
        if (id === undefined) return { skills: [], complete: true, error: NO_SESSION }
        if (market === undefined) throw new Error('the dshMarketPro Remote is not mounted')
        const result = await market.listSkills(id)
        if (!result.ok) throw new Error(result.error.code + ': ' + result.error.message)
        return result.value
      },
      skillsSession: {
        getSnapshot: () => {
          const { phase, id, preset, cwd } = selection()
          return JSON.stringify([phase, id, preset, cwd, skillRevision.getSnapshot()])
        },
        subscribe: (listener: () => void) => {
          const disposeList = sessions.list.subscribe(listener)
          const disposeRevision = skillRevision.subscribe(listener)
          return () => { disposeList(); disposeRevision() }
        },
      },
    }
  }

  const loadCatalog = async (force: boolean): Promise<MarketCatalogResult> => {
    const remote = market
    if (remote === undefined) throw new Error('the dshMarketPro Remote is not mounted')
    const result = await remote.getCatalog(force)
    if (!result.ok) throw new Error(`${result.error.code}: ${result.error.message}`)
    return result.value
  }

  /** The installed-panel verbs: local profile facts, so they need no market switch. */
  const listInstalled = async (): Promise<MarketInstalledResult> => {
    const remote = market
    if (remote === undefined) throw new Error('the dshMarketPro Remote is not mounted')
    const result = await remote.listInstalled()
    if (!result.ok) throw new Error(`${result.error.code}: ${result.error.message}`)
    return result.value
  }

  const subscribeInstalledChanges = (listener: () => void): (() => void) => {
    const offChanged = ctx.remote.$on('plugin-manager/changed', listener)
    const offReset = ctx.on('connection/reset', listener)
    return () => { offChanged(); offReset() }
  }

  const setInstalledEnabled = async (packageName: string, enabled: boolean): Promise<MarketInstalledResult> => {
    const remote = market
    if (remote === undefined) throw new Error('the dshMarketPro Remote is not mounted')
    const result = await remote.setInstalledEnabled({ packageName, enabled })
    if (!result.ok) throw new Error(`${result.error.code}: ${result.error.message}`)
    return result.value
  }

  const uninstallInstalled = async (packageName: string): Promise<MarketInstalledResult> => {
    const remote = market
    if (remote === undefined) throw new Error('the dshMarketPro Remote is not mounted')
    const result = await remote.uninstallInstalled({ packageName })
    if (!result.ok) throw new Error(`${result.error.code}: ${result.error.message}`)
    return result.value
  }

  /**
   * The second half of every review hand-off: connect the workspace, navigate
   * to its session, and write the draft. Every step goes through a published
   * service face; nothing here reads the DOM, and nothing here sends.
   */
  const stageIn = async (workspaceId: WorkspaceTarget, prompt: string): Promise<InstallOutcome> => {
    return stageReviewPrompt(sessions, navigation, ctx.get('conversation') as IConversation, workspaceId, prompt)
  }

  /**
   * Register a directory as a Workspace, through the Host's own picker.
   *
   * The directory is the one thing here that cannot be inferred: it is where
   * the agent will work, so the choice stays with the person making it. What
   * this removes is the errand — the old answer sent them to the sidebar and
   * asked them to come back and start over.
   */
  const chooseWorkspaceId = async (): Promise<
    | { ok: true; id: WorkspaceTarget; path: string }
    | { ok: false; reason: 'cancelled' }
    | { ok: false; reason: 'failed'; message: string }
  > => {
    try {
      const path = await navigation.pickDirectory()
      // A cancelled picker is an answer, not a failure: the user changed
      // their mind, and the card says so instead of showing an error.
      if (path === null) return { ok: false, reason: 'cancelled' }
      const created = await workspaces.create({ path })
      // `openWorkspace` resolves against the list mirror, which the create
      // response reaches one projection later.
      const deadline = Date.now() + WORKSPACE_WAIT_MS
      while (Date.now() < deadline
        && !workspaces.list.getSnapshot().items.some(item => item.workspaceId === created.workspaceId)) {
        await wait(WORKSPACE_POLL_MS)
      }
      return { ok: true, id: created.workspaceId, path }
    } catch (error) {
      return { ok: false, reason: 'failed', message: error instanceof Error ? error.message : String(error) }
    }
  }

  /**
   * The review hand-off: resolve the workspace, then stage the prompt in it.
   */
  const install = async (prompt: string): Promise<InstallOutcome> => {
    // The same target rule the shell's own New Session action uses: the
    // current session's workspace, then the recency projection. Both derive
    // from the two-baseline readiness flag — in the first moments of boot
    // `items` is still empty and "no workspace yet" would be a wrong answer.
    const workspaceState = workspaces.list.getSnapshot()
    const sessionState = sessions.list.getSnapshot()
    if (!workspaceReady(workspaceState, sessionState)) return { ok: false, reason: 'not-ready' }
    const workspaceId = workspaceTargetOf(
      workspaceState,
      sessionState,
    )
    if (workspaceId === undefined) return { ok: false, reason: 'no-workspace' }
    return await stageIn(workspaceId, prompt)
  }

  /** The review hand-off for a deployment with no workspace yet. */
  const installIntoNewWorkspace = async (prompt: string): Promise<InstallOutcome> => {
    const chosen = await chooseWorkspaceId()
    if (!chosen.ok) return chosen
    return await stageIn(chosen.id, prompt)
  }

  /** Pick and register a workspace on its own, for the page's standing notice. */
  const chooseWorkspace = async (): Promise<ChooseWorkspaceOutcome> => {
    const chosen = await chooseWorkspaceId()
    return chosen.ok ? { ok: true, path: chosen.path } : chosen
  }

  /**
   * Live workspace readiness for the notice at the top of the Plugins page,
   * read straight off the domain's own list store so it clears itself the
   * moment a workspace appears — from this flow or from anywhere else.
   */
  const workspaceReadiness = {
    getSnapshot: (): WorkspaceReadiness => {
      const state = workspaces.list.getSnapshot()
      if (!workspaceReady(state, sessions.list.getSnapshot())) return 'pending'
      return state.items.length > 0 ? 'present' : 'none'
    },
    subscribe: (fn: () => void): (() => void) => {
      const disposeWorkspaces = workspaces.list.subscribe(fn)
      const disposeSessions = sessions.list.subscribe(fn)
      return () => {
        disposeSessions()
        disposeWorkspaces()
      }
    },
  }

  const directInstaller = createDirectInstaller(() => ctx.reflect.get('remote.pluginManager') as InstallHost | undefined)
  const pluginUpdater = createPluginUpdater(
    () => ctx.reflect.get('remote.pluginManager') as UpdateHost | undefined,
    () => ctx.reflect.get('remote.pluginMarket') as UpdateMarketHost | undefined,
  )
  ctx.effect(() => ctx.remote.$on('plugin-manager/update-state', progress => pluginUpdater.progress(progress)), 'dsh-market-pro: update progress')

  // The Host's own path opener (the session namespace the conversation UI
  // uses for opening files). It re-verifies the path on the Host and reports
  // whether this deployment has a desktop to open it on at all.
  const sessionRemote = (): SessionPathFace | undefined => ctx.reflect.get('remote.session') as SessionPathFace | undefined
  const canOpenFolder = async (): Promise<boolean> => {
    const remote = sessionRemote()
    if (remote === undefined) return false
    const result = await remote.canOpenWorkspacePath()
    return result.ok && result.value
  }
  const openFolder = async (path: string): Promise<void> => {
    const remote = sessionRemote()
    if (remote === undefined) throw new Error('the session Remote is not mounted')
    const result = await remote.openWorkspacePath({ path })
    if (!result.ok) throw new Error(result.error.message)
  }

  // The MCP page reads the official manager, Settings and credential Remotes
  // directly; only the facts they cannot carry come through this market.
  const reflect = (name: string): unknown => (ctx.reflect as unknown as { get(name: string): unknown }).get(name)
  const mcp = createMcpController({
    manager: () => reflect('remote.mcpManager') as McpManagerFace | undefined,
    settings: () => reflect('remote.settings') as McpSettingsFace | undefined,
    credentials: () => reflect('remote.credentials') as McpCredentialsFace | undefined,
    plugins: () => reflect('remote.pluginManager') as McpPluginsFace | undefined,
    inspect: async () => {
      const remote = market
      if (remote === undefined) throw new Error('the dshMarketPro Remote is not mounted')
      const result = await remote.inspectMcp()
      if (!result.ok) throw new Error(`${result.error.code}: ${result.error.message}`)
      return result.value
    },
    adopt: async (loaderId) => {
      const remote = market
      if (remote === undefined) throw new Error('the dshMarketPro Remote is not mounted')
      const result = await remote.adoptMcp({ loaderId })
      if (!result.ok) throw new Error(`${result.error.code}: ${result.error.message}`)
      return result.value
    },
  })
  ctx.on('connection/reset', () => { mcp.reset() })
  ctx.effect(() => ctx.remote.$on('plugin-manager/changed', () => { mcp.invalidate() }), 'dsh-market-pro: mcp plugin changes')
  // Forwarded Host events: an edit made elsewhere (another window, the
  // settings file, a credential rotation) reaches the open page.
  ctx.effect(() => ctx.remote.$on('settings/document-updated', () => { mcp.settingsChanged() }), 'dsh-market-pro: mcp settings changes')
  ctx.effect(() => ctx.remote.$on('credentials/reference-updated', () => { mcp.credentialsChanged() }), 'dsh-market-pro: mcp credential changes')

  const globalSkills = skillsFor()
  const injectMarket = (): MarketSectionInjected => ({
    hooks: { scope },
    directInstaller,
    pluginUpdater,
    loadCatalog,
    ...globalSkills,
    canOpenFolder,
    openFolder,
    install,
    installIntoNewWorkspace,
    chooseWorkspace,
    workspaceReadiness,
    listInstalled,
    subscribeInstalledChanges,
    setInstalledEnabled,
    uninstallInstalled,
    mcp,
  })

  registerMarketSidebar(ctx, injectMarket)
  registerMarketNavigation(ctx, injectMarket)
  registerMarketPluginTab(ctx, injectMarket)
  const t = ctx.locale.bind(NS)
  ctx.effect(() => ctx.slots.inject('conversation.view', () => ctx.slots.register({
    name: 'conversation.view',
    id: 'dsh-market-pro-skills',
    order: 30,
    locale: NS,
    label: () => t('tab.skills'),
    inject: (sessionId) => ({ ...skillsFor(sessionId), canOpenFolder, openFolder }),
  }, ProjectSkillsView)), 'dsh-market-pro: conversation skills tab')

}
